<http://www.example.org/ontology#UNEDIFACTStory>
    rdf:type owl:Ontology ;
    rdfs:label "UN/EDIFACT Digital Business Document Ontology" ;
    rdfs:comment "Ontology modeling the structure of UN/EDIFACT digital business documents, their segments, roles, and alignment with EN 16931-1 and P2P-O." .

#################################################################
# Classes
#################################################################
:InterchangeEnvelope rdf:type owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The top-level envelope in UN/EDIFACT containing messages." .

:Message rdf:type owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A business document message within an InterchangeEnvelope." .

:InvoiceMessage rdf:type owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "A message representing an invoice in UN/EDIFACT." .

:Segment rdf:type owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment in a message, e.g., BGM, NAD." .

:CompositeDataElement rdf:type owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite element within a segment." .

:SimpleDataElement rdf:type owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite data element." .

:Section rdf:type owl:Class ;
    rdfs:label "Section" ;
    rdfs:comment "A generic section in an invoice message." .

:HeaderSection rdf:type owl:Class ;
    rdfs:subClassOf :Section ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice message containing dates and references." .

:DetailSection rdf:type owl:Class ;
    rdfs:subClassOf :Section ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail section listing line items." .

:SummarySection rdf:type owl:Class ;
    rdfs:subClassOf :Section ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section with totals and tax." .

:LineItem rdf:type owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A line item in the invoice, associated with an item and price." .

:Item rdf:type owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "An item sold in the invoice." .

:Price rdf:type owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price for a line item." .

:Organization rdf:type owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the invoice, e.g., buyer or seller." .

:AgentRole rdf:type owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in a business process." .

:Address rdf:type owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "An address associated with an organization role assignment." .

:BusinessProcess rdf:type owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which an invoice can be assigned." .

:OrganizationRoleAssignment rdf:type owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "Reifies the relationship between an Organization, the role it plays, and the address relevant for that role in a given InvoiceMessage." .

#################################################################
# Disjointness and DisjointUnion
#################################################################
:Organization owl:disjointWith :Segment, :Item, :Section, :BusinessProcess, :Price .

:Section owl:disjointUnionOf ( :HeaderSection :DetailSection :SummarySection ) .

