#################################################################
# AgentRole Subclasses via Equivalence (GCAs)
#################################################################
:BuyerRole rdf:type owl:Class ;
    rdfs:subClassOf :AgentRole ;
    owl:equivalentClass [
        rdf:type owl:Class ;
        owl:intersectionOf (
            :AgentRole
            [ rdf:type owl:Restriction ;
              owl:onProperty :hasRoleIdentifier ;
              owl:hasValue "BY"
            ]
        )
    ] ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "AgentRole with role identifier 'BY' (Buyer)." .

:SellerRole rdf:type owl:Class ;
    rdfs:subClassOf :AgentRole ;
    owl:equivalentClass [
        rdf:type owl:Class ;
        owl:intersectionOf (
            :AgentRole
            [ rdf:type owl:Restriction ;
              owl:onProperty :hasRoleIdentifier ;
              owl:hasValue "SE"
            ]
        )
    ] ;
    rdfs:label "Seller Role" ;
    rdfs:comment "AgentRole with role identifier 'SE' (Seller)." .

